---

## 2️⃣ Full‑Control Player Using the **Widget API**

The widget API lets you programmatically control playback, listen for events, and swap tracks without reloading the page.

### 2.1 Add the widget script

```html
<script src="https://w.soundcloud.com/player/api.js"></script>
```

### 2.2 HTML skeleton

```html
<div id="player-container">
  <!-- The iframe will be created by JavaScript -->
</div>

<button id="play">Play</button>
<button id="pause">Pause</button>
<button id="next">Load Next Track</button>
<span id="status"></span>
```

### 2.3 JavaScript (vanilla)

```html
<script>
  // 1️⃣ List of track IDs you want to cycle through (you can fetch these via the API)
  const trackIds = [
    '123456789', // replace with real IDs
    '987654321',
    '1122334455'
  ];
  let current = 0;

  // 2️⃣ Build the iframe URL
  function buildIframeUrl(trackId) {
    const base = 'https://w.soundcloud.com/player/';
    const params = new URLSearchParams({
      url: `https://api.soundcloud.com/tracks/${trackId}`,
      color: '#ff5500',
      auto_play: false,
      hide_related: false,
      show_comments: true,
      show_user: true,
      show_reposts: false,
      visual: true
    });
    return `${base}?${params.toString()}`;
  }

  // 3️⃣ Insert the iframe
  const container = document.getElementById('player-container');
  const iframe = document.createElement('iframe');
  iframe.setAttribute('allow', 'autoplay');
  iframe.setAttribute('scrolling', 'no');
  iframe.setAttribute('frameborder', 'no');
  iframe.setAttribute('width', '100%');
  iframe.setAttribute('height', '300');
  iframe.src = buildIframeUrl(trackIds[current]);
  container.appendChild(iframe);

  // 4️⃣ Create the widget object
  const widget = SC.Widget(iframe);

  // 5️⃣ Hook up UI controls
  document.getElementById('play').onclick = () => widget.play();
  document.getElementById('pause').onclick = () => widget.pause();

  document.getElementById('next').onclick = () => {
    current = (current + 1) % trackIds.length;
    widget.load(buildIframeUrl(trackIds[current]), {
      // optional: start playing automatically
      auto_play: true
    });
  };

  // 6️⃣ Listen for events (optional but handy)
  widget.bind(SC.Widget.Events.PLAY, () => {
    document.getElementById('status').textContent = '▶️ Playing';
  });
  widget.bind(SC.Widget.Events.PAUSE, () => {
    document.getElementById('status').textContent = '⏸️ Paused';
  });
  widget.bind(SC.Widget.Events.FINISH, () => {
    document.getElementById('status').textContent = '✅ Finished';
  });
</script>
```

**What this does**

* Loads a SoundCloud track into an iframe.
* Gives you `play()`, `pause()`, `load()` and many other methods (`seekTo`, `setVolume`, `getCurrentSound`, etc.).
* Fires events you can react to (e.g., update UI when a track ends).

